              {
                "op": "count",
                "args": [{
                  "op": "induced_edges",
                  "args": [{
                    "op": "intersection",
                    "args": [
                      {"op": "neighbors", "args": [{"op": "root", "args": []}]},
                      {"op": "available", "args": []}
                    ]
