          },
          {
            "op": "count",
            "args": [{
              "op": "induced_edges",
              "args": [{
                "op": "difference",
                "args": [
                  {
                    "op": "difference",
                    "args": [
                      {"op": "available", "args": []},
                      {"op": "neighbors", "args": [{"op": "root", "args": []}]}
